// ============================================================================
//  Clint -> Planilha | Mapear negócio ganho para colunas
//  Nativos + valor (deal.value) + dias para ganhar + UTM (deal.fields).
// ============================================================================

// ==== CONFIG ================================================================
// O valor é NATIVO (deal.value). Deixe '' — não precisa configurar nada.
const VALUE_FIELD_LABEL = '';
// Fuso horário para formatar as datas (ISO -> legível).
const TIMEZONE = 'Europe/Lisbon';
// ============================================================================

const STATUS_PT = { WON: 'Ganho', OPEN: 'Aberto', LOST: 'Perdido' };

function fmtDate(iso) {
  if (!iso) return '';
  const d = new Date(iso);
  if (isNaN(d.getTime())) return String(iso);
  return d.toLocaleString('pt-PT', { timeZone: TIMEZONE, dateStyle: 'short', timeStyle: 'short' });
}

// Diferença em dias (inteiro) entre duas datas ISO. '' se faltar alguma.
function diffDays(startIso, endIso) {
  if (!startIso || !endIso) return '';
  const a = new Date(startIso), b = new Date(endIso);
  if (isNaN(a.getTime()) || isNaN(b.getTime())) return '';
  return Math.round((b.getTime() - a.getTime()) / 86400000);
}

// Normaliza o objecto `fields` (formato livre) para uma lista { key, keyLower, value }.
function normalizeFields(fields) {
  const out = [];
  if (!fields || typeof fields !== 'object') return out;
  for (const [k, v] of Object.entries(fields)) {
    let value = v;
    if (v && typeof v === 'object') {
      value = (v.value ?? v.val ?? v.content ?? v.text ?? JSON.stringify(v));
    }
    out.push({ key: k, keyLower: String(k).toLowerCase(), value });
  }
  return out;
}

function isEmpty(v) { return v === '' || v === null || v === undefined; }

// Reúne os negócios de todas as páginas (funciona com 1 pedido ou com paginação).
const inputItems = $input.all();
let deals = [];
for (const it of inputItems) {
  const b = it.json;
  if (b && Array.isArray(b.data)) deals = deals.concat(b.data);
  else if (Array.isArray(b)) deals = deals.concat(b);
  else if (b && b.id) deals.push(b);
}

const label = VALUE_FIELD_LABEL.trim();
const rows = [];

for (const deal of deals) {
  const flat = normalizeFields(deal.fields);

  // ---- valor do negócio fechado (nativo deal.value) ----
  let valor = '';
  if (label) {
    if (!isEmpty(deal[label])) valor = deal[label];
    else { const h = flat.find(f => f.keyLower === label.toLowerCase()); if (h) valor = h.value; }
  }
  if (isEmpty(valor) && !isEmpty(deal.value)) valor = deal.value;
  if (isEmpty(valor)) {
    const h = flat.find(f => /(valor.*fechad|valor|value|amount)/.test(f.keyLower));
    if (h) valor = h.value;
  }

  // ---- parâmetros UTM (qualquer campo com "utm" no nome) ----
  const utm = { utm_source:'', utm_medium:'', utm_campaign:'', utm_content:'', utm_term:'', utm_id:'' };
  for (const f of flat) {
    if (f.keyLower.includes('utm')) {
      const m = f.keyLower.match(/utm[_-]?([a-z]+)/);
      const norm = m ? ('utm_' + m[1]) : f.keyLower;
      utm[norm] = f.value;
    }
  }

  rows.push({
    id_negocio: deal.id || '',
    estado: STATUS_PT[deal.status] || deal.status || '',
    contacto_nome: ((deal.contact && deal.contact.name) || '').trim(),
    contacto_email: (deal.contact && deal.contact.email) || '',
    contacto_telefone: (deal.contact && deal.contact.phone) || '',
    responsavel: ((deal.user && deal.user.full_name) || '').trim(),
    valor_fechado: isEmpty(valor) ? '' : valor,
    moeda: deal.currency || '',
    criado_em: fmtDate(deal.created_at),
    ganho_em: fmtDate(deal.won_at),
    dias_para_ganhar: diffDays(deal.created_at, deal.won_at),
    etapa: deal.stage || '',
    etapa_id: deal.stage_id || '',
    origem_id: deal.origin_id || '',
    ...utm,
  });
}

return rows.map(r => ({ json: r }));
